  data() {
    return{
      title:'修改',
    }
  },
  methods:{
    editClick(){
           let text = this.titleText;
           if(this.title === '修改'){
            this.$emit('edit',text);
            this.title = '保存';
           }else{
            this.$emit('save',text);
           }
    },
    saveClick(){
      let text = this.titleText;
      this.$emit('save',text);

    },

    setBtnTitleC(){
      this.title = '修改';
    },
  },
}
